import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/app/data/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        email TEXT,
        department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        query_text TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department with optional role filter.
    Supports partial matching for department names.
    """
    department = request.args.get('department', '')
    role_filter = request.args.get('role', '')

    # Build search query with department filter
    base_query = "SELECT id, username, email, department, role FROM users WHERE department LIKE '%" + department + "%'"

    if role_filter:
        # Additional filter - parameterized (looks safe)
        base_query += " AND role = ?"
        cursor = get_db().execute(base_query, (role_filter,))
    else:
        cursor = get_db().execute(base_query)

    results = [dict(row) for row in cursor.fetchall()]

    # Log the search for compliance
    log_query = "INSERT INTO audit_log (action, query_text) VALUES (?, ?)"
    get_db().execute(log_query, ('user_search', f'dept={department},role={role_filter}'))
    get_db().commit()

    return jsonify({'results': results, 'count': len(results)})

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID."""
    cursor = get_db().execute(
        "SELECT id, username, email, department, role FROM users WHERE id = ?",
        (user_id,)
    )
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'User not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user account."""
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    password_hash = hashlib.sha256(data['password'].encode()).hexdigest()

    try:
        get_db().execute(
            "INSERT INTO users (username, password_hash, email, department) VALUES (?, ?, ?, ?)",
            (data['username'], password_hash, data.get('email', ''), data.get('department', ''))
        )
        get_db().commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/api/health', methods=['GET'])
def health_check():
    return jsonify({'status': 'healthy', 'version': '2.1.4'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
